702	# 客户编号可表示的最大值（SQLite INTEGER 上限，2^63 - 1）。
703	# 超过它的整数无法作为编号保存或查询，必须在进入数据库前明确拒绝。
704	MAX_CLIENT_ID = 9223372036854775807
