706	# SQLite 单条语句允许的最大绑定参数数量（SQLITE_MAX_VARIABLE_NUMBER）。
707	# 不同版本取值不同（历史上 999、32766，较新版本 250000），因此以运行时
708	# 查询为准；批量修改一次选择的客户数可能超过它，不能把全部编号塞进单条
709	# 语句的 IN(?,…)，必须分块执行。
710	DEFAULT_SQL_VARIABLE_LIMIT = 999
711	COMPILE_OPTION_PREFIX = "MAX_VARIABLE_NUMBER="
