714	def sql_variable_limit(database):
715	    """返回运行时 SQLite 单条语句可绑定的最大参数数量。
716	
717	    取自编译选项 MAX_VARIABLE_NUMBER（各 SQLite 版本默认值不同：999、32766、
718	    250000）；取不到时回退到保守的历史默认值 999。
719	    """
720	    try:
721	        for (option,) in database.execute("PRAGMA compile_options"):
722	            if option.startswith(COMPILE_OPTION_PREFIX):
723	                limit = int(option[len(COMPILE_OPTION_PREFIX):])
724	                if limit > 0:
725	                    return limit
726	    except (sqlite3.DatabaseError, ValueError):
727	        pass
728	    return DEFAULT_SQL_VARIABLE_LIMIT
