759	    """
760	    if not isinstance(payload, dict):
761	        raise BatchUpdateError("请求体必须是 JSON 对象")
762	
763	    raw_ids = payload.get("ids")
764	    if not isinstance(raw_ids, list):
765	        raise BatchUpdateError("ids 必须是客户编号数组")
766	    if not raw_ids:
767	        raise BatchUpdateError("未选择客户：请先勾选至少一名客户")
768	
769	    ids = []
770	    seen_ids = set()
771	    for raw_id in raw_ids:
772	        if isinstance(raw_id, bool) or not isinstance(raw_id, int) or raw_id <= 0:
773	            raise BatchUpdateError("客户编号必须是正整数：%r 不合法" % (raw_id,))
774	        if raw_id > MAX_CLIENT_ID:
775	            raise BatchUpdateError(
776	                "客户编号超出可接受范围：%d（编号须在 1 到 %d 之间）"
777	                % (raw_id, MAX_CLIENT_ID))
778	        if raw_id not in seen_ids:
779	            seen_ids.add(raw_id)
780	            ids.append(raw_id)
781	
782	    raw_updates = payload.get("updates", {})
783	    if not isinstance(raw_updates, dict):
784	        raise BatchUpdateError("updates 必须是字段修改说明对象")
785	    extra = [key for key in raw_updates if key not in OPTIONAL_FIELDS]
786	    if extra:
787	        raise BatchUpdateError("包含不能修改或不存在的字段：%s" % "、".join(extra))
788	
789	    actions = {}
790	    for field_name in OPTIONAL_FIELDS:
791	        spec = raw_updates.get(field_name, {"op": "keep"})
792	        if not isinstance(spec, dict):
793	            raise BatchUpdateError("%s的修改说明必须是对象" % FIELD_LABELS[field_name])
794	        op = spec.get("op")
795	        if op not in ("keep", "set", "clear"):
796	            raise BatchUpdateError(
797	                "%s的操作必须是 keep、set 或 clear 之一" % FIELD_LABELS[field_name])
798	        if op == "keep":
799	            continue
800	        if op == "clear":
801	            actions[field_name] = None
802	        else:
803	            actions[field_name] = _normalize_set_value(field_name, spec.get("value"))
804	
