808	    # 一次选择的客户数可能超过 SQLite 单条语句的参数上限，存在性检查与 UPDATE
809	    # 都按参数上限分块；UPDATE 的多个分块在同一事务内一次提交，整笔修改要么
810	    # 全部生效要么全部不生效，不会因分块变成多次部分修改。
811	    variable_limit = sql_variable_limit(database)
812	
813	    existing = set()
814	    for id_chunk in _chunked(ids, variable_limit):
815	        placeholders = ",".join("?" for _ in id_chunk)
816	        existing.update(
817	            row[0]
818	            for row in database.execute(
819	                "SELECT id FROM clients WHERE id IN (%s)" % placeholders, id_chunk
820	            )
821	        )
822	    missing = [cid for cid in ids if cid not in existing]
823	    if missing:
824	        raise BatchUpdateError("找不到对应客户，编号：%s" % "、".join(str(c) for c in missing))
825	
826	    # 每条 UPDATE 还要为每个修改字段绑定一个赋值参数，编号分块需相应留出位置。
827	    id_chunk_size = max(1, variable_limit - len(actions))
828	    assignments = ", ".join("%s = ?" % field_name for field_name in actions)
829	    values = list(actions.values())
830	    try:
831	        for id_chunk in _chunked(ids, id_chunk_size):
832	            placeholders = ",".join("?" for _ in id_chunk)
833	            database.execute(
834	                "UPDATE clients SET %s WHERE id IN (%s)" % (assignments, placeholders),
835	                values + id_chunk,
836	            )
837	        database.commit()
838	    except sqlite3.DatabaseError:
839	        database.rollback()
840	        raise BatchUpdateError("保存失败：数据库错误，本次修改未生效")
