845	def parse_csv(text):
846	    """解析 RFC 4180 风格 CSV，返回 (header, data_rows)。
847	
848	    支持引号包裹的字段、引号内逗号与换行、双引号转义；
849	    引号外支持 LF / CRLF / CR 换行。结构损坏时抛 FileError：
850	    - 未加引号的字段中出现双引号（双引号只能在字段开头用于包住整个字段）；
851	    - 结束引号后出现逗号、换行或文件结束以外的字符（含空格）；
852	    - 文件结束时仍有字段处于引号内（引号未闭合）。
853	    错误信息区分上述三种情况，并指出发生在表头还是第 N 条数据记录
854	    （数据记录编号不包含表头，引号字段内的换行不增加编号）。
855	    """
856	    rows = []
857	    record = []
858	    field = []
859	    quoted = False        # 当前字段处于引号内
860	    started = False       # 当前字段已经开始（已有内容或已进入引号）
861	    closed = False       # 引号字段刚结束，等待逗号 / 换行 / 文件结束
862	    record_number = 0     # 0 = 表头，1 起为数据记录
863	    i = 0
864	    n = len(text)
865	
866	    def location():
867	        return "表头" if record_number == 0 else "第 %d 条数据记录" % record_number
868	
869	    def structure_error(kind):
870	        raise FileError("CSV 结构损坏（%s）：%s" % (location(), kind))
871	
872	    def finish_record():
873	        nonlocal record, field, started, closed
874	        record.append("".join(field))
875	        rows.append(record)
876	        record = []
877	        field = []
878	        started = False
879	        closed = False
880	
881	    while i < n:
882	        c = text[i]
883	        if quoted:
884	            if c == '"':
885	                if i + 1 < n and text[i + 1] == '"':
886	                    field.append('"')
887	                    i += 2
888	                    continue
889	                quoted = False
890	                closed = True
891	                i += 1
892	                continue
893	            if c == "\r":
894	                # 统一字段内换行符为 LF
895	                if i + 1 < n and text[i + 1] == "\n":
896	                    i += 1
897	                field.append("\n")
898	                i += 1
899	                continue
900	            field.append(c)
901	            i += 1
902	            continue
903	        if closed:
904	            # 引号已结束，只允许逗号、记录换行或文件结束
905	            if c == ",":
906	                record.append("".join(field))
907	                field = []
908	                started = False
909	                closed = False
910	            elif c in "\r\n":
911	                if c == "\r" and i + 1 < n and text[i + 1] == "\n":
912	                    i += 1
913	                finish_record()
914	                record_number += 1
915	            else:
916	                structure_error("结束引号后有多余字符，结束引号后只能紧接逗号、记录换行或文件结束")
917	            i += 1
918	            continue
919	        if c == '"' and not started:
920	            quoted = True
921	            started = True
922	        elif c == '"':
923	            structure_error("未加引号的字段中出现双引号，双引号只能在字段开头用于包住整个字段")
924	        elif c == ",":
925	            record.append("".join(field))
926	            field = []
927	            started = False
928	        elif c in "\r\n":
929	            if c == "\r" and i + 1 < n and text[i + 1] == "\n":
930	                i += 1
931	            if not started and not record and not field:
932	                # 空白行：不作为数据记录（显式的 "" 空字段 started=True，仍会保留）
933	                i += 1
934	                continue
935	            finish_record()
936	            record_number += 1
937	        else:
938	            field.append(c)
939	            started = True
940	        i += 1
941	    if quoted:
942	        structure_error("引号未闭合，文件结束时仍有字段处于引号内")
943	    if started or field or record or closed:
944	        record.append("".join(field))
945	        rows.append(record)
946	    if not rows:
947	        raise FileError("CSV 内容为空：缺少表头")
948	    return rows[0], rows[1:]
