951	def check_date(value):
952	    """校验 YYYY-MM-DD 且为真实日历日期，返回 (是否合法, 错误原因)。"""
953	    match = DATE_RE.match(value)
954	    if not match:
955	        return False, "重要日期格式无效（%s）：须为 YYYY-MM-DD" % value
956	    try:
957	        datetime.date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
958	    except ValueError:
959	        return False, "重要日期无效（%s）：不是真实日历日期" % value
960	    return True, None
