// 把 JSON 文本中字符串的「值内容」替换为等长空格，键字符串（后面紧跟冒号）保留
// 原文，转义（如 \\"）不改变串内外状态。替换后长度与原文逐字符对齐，可直接用
// 正则在掩码上定位结构键，再按同一位置从原文切出未经 Number 处理的编号原文。
function maskJsonStringValues(raw) {
  let out = "";
  let j = 0;
  const n = raw.length;
  while (j < n) {
    if (raw[j] !== '"') {
      out += raw[j];
      j++;
      continue;
    }
    const start = j;
    j++;
    while (j < n) {
      if (raw[j] === "\\") j += 2;
      else if (raw[j] === '"') break;
      else j++;
    }
    const close = j; // 闭合引号位置（能走到这里说明 JSON.parse 已验证过结构）
    j = close + 1;
    let k = j;
    while (k < n && (raw[k] === " " || raw[k] === "\t" ||
                     raw[k] === "\n" || raw[k] === "\r")) k++;
    if (raw[k] === ":") {
      out += raw.slice(start, j); // 键：保留原文
    } else {
      out += '"' + " ".repeat(Math.max(0, close - start - 1)) + '"'; // 值：掩码
    }
  }
  return out;
}

